import networkx as nx
import itertools
import random

def is_girth_at_least_5(G):
    try:
        girth = nx.girth(G)
        return girth >= 5
    except:
        return False

def find_graph():
    # Try to find a 3-regular graph with 14 vertices and girth >= 5
    # A simple way is to generate random 3-regular graphs and check the girth
    for _ in range(10000):
        G = nx.random_regular_graph(3, 14)
        if is_girth_at_least_5(G):
            return list(G.edges())
    return None

edges = find_graph()
print(edges)
